"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  ArrowUp,
  Check,
  ChevronDown,
  Code2,
  Compass,
  FileText,
  Folder,
  Lightbulb,
  MessageSquare,
  PanelLeft,
  Paperclip,
  PenLine,
  Plus,
  Search,
  Settings,
  Sparkles,
  type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Role = "user" | "assistant";
type Message = { id: number; role: Role; text: string };
type Thread = { id: number; title: string; when: "Today" | "Yesterday" | "Earlier"; messages: Message[] };
type View = "chat" | "projects" | "library" | "settings";
type Prefs = { memory: boolean; sounds: boolean; suggestions: boolean };

const MODELS = [
  { id: "swift", name: "Swift", note: "Fast, for everyday questions" },
  { id: "deep", name: "Deep", note: "Slower, thinks it through" },
  { id: "write", name: "Write", note: "Tuned for long form text" },
];

const STARTERS: { icon: LucideIcon; title: string; prompt: string }[] = [
  { icon: PenLine, title: "Draft a launch email", prompt: "Draft a short launch email for a new design tool aimed at small teams." },
  { icon: Code2, title: "Explain this error", prompt: "Explain what a hydration mismatch is in React and how to fix one." },
  { icon: Lightbulb, title: "Brainstorm names", prompt: "Give me ten calm, memorable names for a notes app." },
  { icon: Compass, title: "Plan my week", prompt: "Help me plan a focused week with two deep work blocks a day." },
];

const m = (id: number, role: Role, text: string): Message => ({ id, role, text });
const SEED: Thread[] = [
  {
    id: 1,
    title: "Launch email draft",
    when: "Today",
    messages: [
      m(1, "user", "Write a launch email for Fieldnotes, a notes app for researchers."),
      m(2, "assistant", "Subject: Fieldnotes is here\n\nHi there,\n\nResearch is mostly remembering. Fieldnotes keeps every source, quote and half-formed idea in one calm place, and finds them again when you need them.\n\nTry it free for 30 days. No card needed.\n\nThe Fieldnotes team"),
    ],
  },
  {
    id: 2,
    title: "Pricing page copy",
    when: "Today",
    messages: [
      m(3, "user", "Give me three headline options for a pricing page with a free tier."),
      m(4, "assistant", "1. Start free. Pay when it earns it.\n2. Simple pricing, no surprises.\n3. Free for you, fair for your team."),
    ],
  },
  {
    id: 3,
    title: "Hydration mismatch",
    when: "Yesterday",
    messages: [
      m(5, "user", "What causes a hydration mismatch in React?"),
      m(6, "assistant", "It happens when the HTML the server rendered differs from what React renders first on the client. Common causes are dates, random values and reading window during render. Move that work into an effect, or render it only after mount."),
    ],
  },
  {
    id: 4,
    title: "Naming the notes app",
    when: "Earlier",
    messages: [
      m(7, "user", "Ten calm names for a notes app."),
      m(8, "assistant", "Margin, Fieldnotes, Folio, Quill, Ledger, Verso, Tideline, Lantern, Sill, Common."),
    ],
  },
];

const PROJECTS = [
  { name: "Fieldnotes launch", chats: 6, files: 12, updated: "2h ago" },
  { name: "Website rewrite", chats: 11, files: 4, updated: "Yesterday" },
  { name: "Research reading list", chats: 3, files: 28, updated: "3 days ago" },
  { name: "Investor update", chats: 2, files: 5, updated: "Last week" },
];

const LIBRARY = [
  { title: "Tone of voice", kind: "Prompt", body: "Plain, warm and specific. No filler. Short sentences. Prefer verbs." },
  { title: "Weekly summary", kind: "Prompt", body: "Summarise the notes below into five bullets and one decision I need to make." },
  { title: "Interview questions", kind: "Template", body: "Ten open questions for a user interview about how people take notes today." },
  { title: "Release notes", kind: "Template", body: "Turn this changelog into friendly release notes grouped by what users will notice." },
  { title: "Brand guidelines.pdf", kind: "File", body: "2.4 MB, uploaded last week" },
  { title: "Customer quotes.csv", kind: "File", body: "88 KB, uploaded 3 days ago" },
];

/** A canned reply so the template works with no backend. Swap this for your own API call. */
const replyFor = (q: string) =>
  `Here is a first pass on “${q.length > 60 ? q.slice(0, 57) + "…" : q}”.\n\nStart with the one thing the reader should remember, then support it with two short points. Keep sentences plain and let the structure do the work. If you want, I can tighten it, make it warmer, or turn it into three variants to compare.`;

function Typing() {
  return (
    <span className="inline-flex items-center gap-1 py-1" aria-label="Thinking">
      {[0, 1, 2].map((i) => (
        <motion.span key={i} className="size-1.5 rounded-full bg-muted-foreground" animate={{ opacity: [0.25, 1, 0.25], y: [0, -3, 0] }} transition={{ duration: 1, repeat: Infinity, delay: i * 0.15 }} />
      ))}
    </span>
  );
}

function Switch({ on, label, onChange }: { on: boolean; label: string; onChange: () => void }) {
  return (
    <button type="button" role="switch" aria-checked={on} aria-label={label} onClick={onChange} className={cn("relative h-6 w-10 shrink-0 rounded-full transition-colors", on ? "bg-primary" : "bg-border")}>
      <span className={cn("absolute top-0.5 size-5 rounded-full bg-background shadow transition-all", on ? "left-[1.1rem]" : "left-0.5")} />
    </button>
  );
}

function ProjectsView({ onOpen }: { onOpen: () => void }) {
  return (
    <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-8">
      <div className="mx-auto max-w-3xl">
        <p className="text-sm text-muted-foreground">Group chats, files and instructions that belong together.</p>
        <ul className="mt-6 grid gap-3 sm:grid-cols-2">
          {PROJECTS.map((p, i) => (
            <motion.li key={p.name} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.06 }}>
              <button type="button" onClick={onOpen} className="group w-full rounded-2xl border bg-card p-5 text-left transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/40">
                <span className="grid size-10 place-items-center rounded-xl bg-muted transition-colors group-hover:bg-primary group-hover:text-primary-foreground">
                  <Folder className="size-[18px]" />
                </span>
                <p className="mt-4 font-medium">{p.name}</p>
                <p className="mt-1 text-xs text-muted-foreground">{p.chats} chats · {p.files} files · {p.updated}</p>
              </button>
            </motion.li>
          ))}
          <li>
            <button type="button" className="grid h-full min-h-32 w-full place-items-center rounded-2xl border border-dashed text-sm text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground">
              <span className="inline-flex items-center gap-2"><Plus className="size-4" /> New project</span>
            </button>
          </li>
        </ul>
      </div>
    </div>
  );
}

function LibraryView({ onUse }: { onUse: (text: string) => void }) {
  const [kind, setKind] = useState("All");
  const list = LIBRARY.filter((l) => kind === "All" || l.kind === kind);
  return (
    <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-8">
      <div className="mx-auto max-w-3xl">
        <div role="tablist" className="inline-flex rounded-full border bg-card p-1">
          {["All", "Prompt", "Template", "File"].map((k) => (
            <button key={k} role="tab" aria-selected={kind === k} onClick={() => setKind(k)} className={cn("rounded-full px-4 py-1.5 text-sm transition-colors", kind === k ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground")}>
              {k}
            </button>
          ))}
        </div>
        <ul className="mt-5 divide-y rounded-2xl border bg-card">
          {list.map((l) => (
            <li key={l.title} className="flex items-center gap-4 p-4">
              <span className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted"><FileText className="size-4" /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium">{l.title}</p>
                <p className="truncate text-xs text-muted-foreground">{l.body}</p>
              </div>
              <span className="hidden rounded-full border px-2.5 py-0.5 text-xs text-muted-foreground sm:block">{l.kind}</span>
              {l.kind !== "File" && (
                <button type="button" onClick={() => onUse(l.body)} className="rounded-full bg-foreground px-3.5 py-1.5 text-xs font-medium text-background transition-opacity hover:opacity-85">Use</button>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

function SettingsView({ tone, setTone, prefs, setPrefs }: { tone: string; setTone: (t: string) => void; prefs: Prefs; setPrefs: (p: Prefs) => void }) {
  const rows: { key: keyof Prefs; title: string; body: string }[] = [
    { key: "memory", title: "Remember what I tell it", body: "Keeps preferences between chats." },
    { key: "suggestions", title: "Show starter suggestions", body: "On the empty chat screen." },
    { key: "sounds", title: "Play a sound when a reply ends", body: "Off by default." },
  ];
  return (
    <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-8">
      <div className="mx-auto max-w-2xl space-y-5">
        <section className="flex items-center gap-4 rounded-2xl border bg-card p-5">
          <span className="grid size-14 place-items-center rounded-full bg-muted text-lg font-medium">AK</span>
          <div>
            <p className="font-medium">Ava Kline</p>
            <p className="text-sm text-muted-foreground">ava@fieldnotes.app · Free plan</p>
          </div>
          <button type="button" className="ml-auto rounded-full border px-4 py-1.5 text-sm transition-colors hover:bg-accent">Upgrade</button>
        </section>
        <section className="rounded-2xl border bg-card p-5">
          <p className="text-sm font-medium">Tone of replies</p>
          <div role="radiogroup" aria-label="Tone" className="mt-3 flex flex-wrap gap-2">
            {["Warm", "Direct", "Playful", "Formal"].map((t) => (
              <button key={t} role="radio" aria-checked={tone === t} onClick={() => setTone(t)} className={cn("rounded-full border px-4 py-1.5 text-sm transition-colors", tone === t ? "border-primary bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground")}>
                {t}
              </button>
            ))}
          </div>
        </section>
        <section className="divide-y rounded-2xl border bg-card">
          {rows.map((r) => (
            <div key={r.key} className="flex items-center justify-between gap-4 p-5">
              <div>
                <p className="text-sm font-medium">{r.title}</p>
                <p className="text-xs text-muted-foreground">{r.body}</p>
              </div>
              <Switch on={prefs[r.key]} label={r.title} onChange={() => setPrefs({ ...prefs, [r.key]: !prefs[r.key] })} />
            </div>
          ))}
        </section>
      </div>
    </div>
  );
}

/**
 * A complete chat app with four pages (chat, projects, library, settings): a slim icon rail, searchable
 * threads, starter cards, a composer with a model switcher and streamed replies. Everything runs on local
 * state, so it works as is. Replace replyFor with your own call to stream real answers.
 */
export function AiChatTemplate({ name = "Parley", className }: { name?: string; className?: string }) {
  const [threads, setThreads] = useState<Thread[]>(SEED);
  const [view, setView] = useState<View>("chat");
  const [activeId, setActiveId] = useState<number | null>(1);
  const [tone, setTone] = useState("Warm");
  const [prefs, setPrefs] = useState<Prefs>({ memory: true, sounds: false, suggestions: true });
  const [panel, setPanel] = useState(true);
  const [query, setQuery] = useState("");
  const [draft, setDraft] = useState("");
  const [model, setModel] = useState(MODELS[0].id);
  const [menu, setMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const next = useRef(100);
  const scroller = useRef<HTMLDivElement>(null);
  const timer = useRef<number | null>(null);

  const active = threads.find((t) => t.id === activeId) ?? null;
  const current = MODELS.find((x) => x.id === model)!;

  useEffect(() => () => { if (timer.current) window.clearInterval(timer.current); }, []);
  useEffect(() => {
    scroller.current?.scrollTo({ top: scroller.current.scrollHeight, behavior: "smooth" });
  }, [active?.messages, view]);

  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    const list = q ? threads.filter((t) => t.title.toLowerCase().includes(q)) : threads;
    return (["Today", "Yesterday", "Earlier"] as const).map((w) => [w, list.filter((t) => t.when === w)] as const).filter(([, l]) => l.length);
  }, [threads, query]);

  const patch = (id: number, fn: (t: Thread) => Thread) => setThreads((cur) => cur.map((t) => (t.id === id ? fn(t) : t)));

  const send = (text: string) => {
    const q = text.trim();
    if (!q || busy) return;
    let id = activeId;
    if (id === null) {
      id = next.current++;
      const tid0 = id;
      setThreads((cur) => [{ id: tid0, title: q.length > 34 ? q.slice(0, 32) + "…" : q, when: "Today", messages: [] }, ...cur]);
      setActiveId(id);
    }
    const tid = id;
    const aId = next.current++;
    patch(tid, (t) => ({ ...t, messages: [...t.messages, { id: next.current++, role: "user", text: q }, { id: aId, role: "assistant", text: "" }] }));
    setDraft("");
    setBusy(true);
    const words = replyFor(q).split(/(\s+)/);
    let i = 0;
    window.setTimeout(() => {
      timer.current = window.setInterval(() => {
        i += 2;
        patch(tid, (t) => ({ ...t, messages: t.messages.map((x) => (x.id === aId ? { ...x, text: words.slice(0, i).join("") } : x)) }));
        if (i >= words.length) {
          if (timer.current) window.clearInterval(timer.current);
          setBusy(false);
        }
      }, 45);
    }, 600);
  };

  const fresh = () => {
    setView("chat");
    setActiveId(null);
    setDraft("");
  };

  const railItems = [
    { icon: MessageSquare, label: "Chat", id: "chat" as const },
    { icon: Folder, label: "Projects", id: "projects" as const },
    { icon: FileText, label: "Library", id: "library" as const },
  ];
  const title = view === "chat" ? (active ? active.title : "New conversation") : { projects: "Projects", library: "Library", settings: "Settings" }[view];

  return (
    <div className={cn("flex h-full min-h-[34rem] w-full overflow-hidden bg-background text-foreground", className)}>
      <nav aria-label="Workspace" className="hidden w-14 shrink-0 flex-col items-center gap-1 border-r bg-card/60 py-3 sm:flex">
        <button type="button" aria-label="New chat" onClick={fresh} className="mb-3 grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground transition-transform hover:scale-105">
          <Sparkles className="size-4" />
        </button>
        {railItems.map(({ icon: Icon, label, id }) => (
          <button key={id} type="button" aria-label={label} aria-current={view === id} onClick={() => setView(id)} className={cn("grid size-9 place-items-center rounded-xl transition-colors", view === id ? "bg-accent text-foreground" : "text-muted-foreground hover:bg-accent hover:text-foreground")}>
            <Icon className="size-[18px]" />
          </button>
        ))}
        <button type="button" aria-label="Settings" aria-current={view === "settings"} onClick={() => setView("settings")} className={cn("mt-auto grid size-9 place-items-center rounded-xl transition-colors", view === "settings" ? "bg-accent text-foreground" : "text-muted-foreground hover:bg-accent hover:text-foreground")}>
          <Settings className="size-[18px]" />
        </button>
        <span className="mt-2 grid size-8 place-items-center rounded-full bg-muted text-xs font-medium">AK</span>
      </nav>

      <AnimatePresence initial={false}>
        {panel && view === "chat" && (
          <motion.aside initial={{ width: 0, opacity: 0 }} animate={{ width: 264, opacity: 1 }} exit={{ width: 0, opacity: 0 }} transition={{ duration: 0.3, ease: [0.32, 0.72, 0, 1] }} className="hidden shrink-0 overflow-hidden border-r md:block">
            <div className="flex h-full w-[264px] flex-col">
              <div className="flex items-center justify-between px-4 pb-2 pt-4">
                <p className="text-sm font-semibold tracking-tight">{name}</p>
                <button type="button" onClick={fresh} className="inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs transition-colors hover:bg-accent">
                  <Plus className="size-3.5" /> New
                </button>
              </div>
              <label className="mx-3 mb-2 flex items-center gap-2 rounded-lg bg-muted px-3 py-2 text-sm text-muted-foreground focus-within:ring-2 focus-within:ring-ring/30">
                <Search className="size-3.5" />
                <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search chats" className="w-full bg-transparent text-foreground outline-none placeholder:text-muted-foreground" />
              </label>
              <div className="flex-1 overflow-y-auto px-2 pb-3">
                {shown.map(([when, list]) => (
                  <div key={when} className="mt-3">
                    <p className="px-2 pb-1 text-[11px] font-medium uppercase tracking-widest text-muted-foreground">{when}</p>
                    {list.map((t) => (
                      <button key={t.id} type="button" onClick={() => setActiveId(t.id)} className={cn("flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-sm transition-colors", t.id === activeId ? "bg-accent text-accent-foreground" : "text-muted-foreground hover:bg-accent/60 hover:text-foreground")}>
                        <MessageSquare className="size-3.5 shrink-0" />
                        <span className="truncate">{t.title}</span>
                      </button>
                    ))}
                  </div>
                ))}
                {shown.length === 0 && <p className="px-3 py-6 text-sm text-muted-foreground">Nothing matches “{query}”.</p>}
              </div>
              <div className="m-3 rounded-2xl border bg-card p-3.5">
                <p className="text-sm font-medium">Free plan</p>
                <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted">
                  <div className="h-full w-2/3 rounded-full bg-primary" />
                </div>
                <p className="mt-2 text-xs text-muted-foreground">20 of 30 messages used today</p>
              </div>
            </div>
          </motion.aside>
        )}
      </AnimatePresence>

      <section className="relative flex min-w-0 flex-1 flex-col">
        <header className="flex h-14 shrink-0 items-center gap-3 px-4">
          {view === "chat" && (
            <button type="button" aria-label={panel ? "Hide threads" : "Show threads"} onClick={() => setPanel((p) => !p)} className="hidden size-9 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground md:grid">
              <PanelLeft className="size-[18px]" />
            </button>
          )}
          <p className="truncate text-sm font-medium">{title}</p>
        </header>

        {view === "projects" && <ProjectsView onOpen={() => setView("chat")} />}
        {view === "library" && <LibraryView onUse={(t) => { setView("chat"); setActiveId(null); setDraft(t); }} />}
        {view === "settings" && <SettingsView tone={tone} setTone={setTone} prefs={prefs} setPrefs={setPrefs} />}

        {view === "chat" && (
          <>
            <div ref={scroller} className="min-h-0 flex-1 overflow-y-auto px-4">
              {!active || active.messages.length === 0 ? (
                <div className="mx-auto flex h-full max-w-2xl flex-col items-center justify-center pb-8 text-center">
                  <motion.h2 initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, ease: [0.32, 0.72, 0, 1] }} className="text-balance text-3xl font-medium tracking-tight sm:text-4xl">
                    What are we working on?
                  </motion.h2>
                  <p className="mt-3 max-w-sm text-sm text-muted-foreground">Ask anything{prefs.suggestions ? ", or start from one of these." : "."}</p>
                  {prefs.suggestions && (
                    <div className="mt-8 grid w-full gap-3 sm:grid-cols-2">
                      {STARTERS.map((s, i) => (
                        <motion.button key={s.title} type="button" initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 + i * 0.07, duration: 0.5, ease: [0.32, 0.72, 0, 1] }} onClick={() => send(s.prompt)} className="group flex items-start gap-3 rounded-2xl border bg-card p-4 text-left transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/40">
                          <span className="grid size-9 shrink-0 place-items-center rounded-xl bg-muted text-foreground/80 transition-colors group-hover:bg-primary group-hover:text-primary-foreground">
                            <s.icon className="size-4" />
                          </span>
                          <span>
                            <span className="block text-sm font-medium">{s.title}</span>
                            <span className="mt-0.5 line-clamp-2 block text-xs text-muted-foreground">{s.prompt}</span>
                          </span>
                        </motion.button>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <ul className="mx-auto max-w-2xl space-y-6 py-6">
                  {active.messages.map((x) => (
                    <motion.li key={x.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={cn("flex gap-3", x.role === "user" && "justify-end")}>
                      {x.role === "assistant" && (
                        <span className="mt-0.5 grid size-7 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground">
                          <Sparkles className="size-3.5" />
                        </span>
                      )}
                      <div className={cn("max-w-[85%] whitespace-pre-wrap text-[15px] leading-relaxed", x.role === "user" ? "rounded-2xl rounded-br-md bg-muted px-4 py-2.5" : "pt-0.5")}>{x.text || <Typing />}</div>
                    </motion.li>
                  ))}
                </ul>
              )}
            </div>

            <div className="shrink-0 px-4 pb-5 pt-2">
              <form onSubmit={(e) => { e.preventDefault(); send(draft); }} className="mx-auto max-w-2xl rounded-3xl border bg-card p-2 shadow-sm transition-shadow focus-within:shadow-lg focus-within:ring-4 focus-within:ring-ring/10">
                <textarea
                  value={draft}
                  onChange={(e) => setDraft(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && !e.shiftKey) {
                      e.preventDefault();
                      send(draft);
                    }
                  }}
                  rows={1}
                  placeholder={`Message ${name}`}
                  className="max-h-40 min-h-11 w-full resize-none bg-transparent px-3 py-2.5 text-[15px] outline-none placeholder:text-muted-foreground"
                />
                <div className="flex items-center justify-between gap-2 px-1 pb-1">
                  <div className="relative flex items-center gap-1">
                    <button type="button" aria-label="Attach a file" className="grid size-9 place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
                      <Paperclip className="size-4" />
                    </button>
                    <button type="button" aria-haspopup="listbox" aria-expanded={menu} onClick={() => setMenu((v) => !v)} className="inline-flex h-9 items-center gap-1.5 rounded-full px-3 text-sm text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
                      {current.name}
                      <ChevronDown className={cn("size-3.5 transition-transform", menu && "rotate-180")} />
                    </button>
                    <AnimatePresence>
                      {menu && (
                        <motion.ul role="listbox" initial={{ opacity: 0, y: 6, scale: 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 6, scale: 0.97 }} transition={{ duration: 0.15 }} className="absolute bottom-11 left-10 z-20 w-64 rounded-2xl border bg-card p-1.5 shadow-xl">
                          {MODELS.map((o) => (
                            <li key={o.id}>
                              <button type="button" role="option" aria-selected={o.id === model} onClick={() => { setModel(o.id); setMenu(false); }} className="flex w-full items-start gap-2 rounded-xl px-3 py-2 text-left transition-colors hover:bg-accent">
                                <Check className={cn("mt-0.5 size-4 shrink-0", o.id === model ? "opacity-100" : "opacity-0")} />
                                <span>
                                  <span className="block text-sm font-medium">{o.name}</span>
                                  <span className="block text-xs text-muted-foreground">{o.note}</span>
                                </span>
                              </button>
                            </li>
                          ))}
                        </motion.ul>
                      )}
                    </AnimatePresence>
                  </div>
                  <button type="submit" aria-label="Send" disabled={!draft.trim() || busy} className="grid size-9 place-items-center rounded-full bg-primary text-primary-foreground transition-all duration-300 hover:scale-105 disabled:scale-100 disabled:bg-muted disabled:text-muted-foreground">
                    <ArrowUp className="size-4" />
                  </button>
                </div>
              </form>
              <p className="mt-2 text-center text-[11px] text-muted-foreground">Replies are generated. Check anything important.</p>
            </div>
          </>
        )}
      </section>
    </div>
  );
}

